#include <iostream>
#include <string>

// GradeBook class definition
class GradeBook {
public:
    // member function that displays a welcome message with a course name parameter
    void displayMessage(std::string courseName) const {
        std::cout << "Welcome to the grade book for\n" << courseName << "!\n";
    }
};

int main() {
    std::string nameOfCourse;
    GradeBook myGradeBook;

    std::cout << "Please enter the course name:\n";
    std::getline(std::cin, nameOfCourse);
    std::cout << "\n";

    // Pass nameOfCourse as an argument to displayMessage
    myGradeBook.displayMessage(nameOfCourse);

    return 0;
}
